(async () => {
  const { env } = await import('node:process');
  const { mkdirSync } = await import('node:fs');
  const path = await import('node:path');
  const text = env.TEXT;
  const outPath = env.OUTPUT_PATH;
  if (!text) throw new Error('Missing required input: text');
  if (!outPath) throw new Error('Missing required input: output_path');
  const dir = path.dirname(outPath);
  try { mkdirSync(dir, { recursive: true }); } catch (e) {}
  globalThis.text = text;
  globalThis.outputPath = outPath;
})();

(async () => {
  const { default: qrImage } = await import('qr-image');
  const { writeFileSync } = await import('node:fs');
  const text = globalThis.text;
  const outPath = globalThis.outputPath;
  if (typeof qrImage.imageSync !== 'function') throw new Error('qr-image: required method imageSync not in exports');
  const pngBuffer = qrImage.imageSync(text, { type: 'png' });
  writeFileSync(outPath, pngBuffer);
  globalThis.result = { output_path: outPath };
})();

(async () => {
  const result = globalThis.result;
  if (!result || !result.output_path) throw new Error('Missing result to emit');
  console.log(JSON.stringify({ output_path: result.output_path }));
})();
